using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// 2) Probe without throwing: TryGetTypeInfo returns false if metadata unavailable
bool found = options.TryGetTypeInfo(typeof(Unresolvable), out JsonTypeInfo? info);
Console.WriteLine($"Metadata for Unresolvable found? {found} (info is null: {info is null})");

// Confirm it works for a known type too
bool foundPerson = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? personInfo2);
Console.WriteLine($"Metadata for Person found? {foundPerson} (type: {personInfo2?.Type.Name})");

public record Person(string Name, int Age);

// Type with no resolver configured — we'll use a resolver that explicitly skips it
[System.Text.Json.Serialization.JsonUnmappedMemberHandling(
    System.Text.Json.Serialization.JsonUnmappedMemberHandling.Disallow)]
public class Unresolvable;

