using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// ─── 1) Strongly-typed retrieval ───────────────────────────────────
// GetTypeInfo<T>() returns JsonTypeInfo<T> directly (no cast needed).
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Typed metadata for: {personInfo.Type.Name}");
Console.WriteLine($"  Kind: {personInfo.Kind}");

// ─── 2) Probe without throwing ─────────────────────────────────────
// Use a resolver that resolves nothing, so TryGetTypeInfo returns false.
var empty = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine() // no resolvers → resolves nothing
};

bool found = empty.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? maybe);
Console.WriteLine($"\nTryGetTypeInfo on empty resolver → found: {found}, info: {maybe?.Type.Name ?? "null"}");

// Same call on the fully-configured options succeeds:
bool found2 = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info2);
Console.WriteLine($"TryGetTypeInfo on full resolver  → found: {found2}, info: {info2?.Type.Name}");

public record Person(string Name, int Age);

